import{_ as a,o as r,c as l,a4 as o}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"什么是架构师","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/architect.md","filePath":"engineering/architect.md"}'),i={name:"engineering/architect.md"};function e(d,t,n,h,s,u){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="什么是架构师" tabindex="-1">什么是架构师 <a class="header-anchor" href="#什么是架构师" aria-label="Permalink to &quot;什么是架构师&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">面试重要性</p><p>⭐⭐⭐⭐ 面试常问&quot;你理解的架构师是什么&quot;或&quot;你做过哪些架构决策&quot;。这篇文章给出可复述的定义框架，并拆开前端、后端两种语境。</p></div><div class="info custom-block"><p class="custom-block-title">本文定位</p><p>回答三个问题：架构师是什么、做什么、怎么想。前端与后端的架构师面对的问题域不同，分开阐述；最后对比两者的核心矛盾差异。</p></div><hr><h2 id="一、一句话定义" tabindex="-1">一、一句话定义 <a class="header-anchor" href="#一、一句话定义" aria-label="Permalink to &quot;一、一句话定义&quot;">​</a></h2><p><strong>架构师不是职位头衔，而是一种决策角色：在约束条件（成本、时间、团队、技术栈）下，做影响范围大、事后难改的结构性决策的人。</strong></p><p>判断标准不是&quot;你叫什么&quot;，而是你做的决策符不符合三个特征：</p><table tabindex="0"><thead><tr><th>特征</th><th>说明</th><th>反例</th></tr></thead><tbody><tr><td><strong>结构性</strong></td><td>决定模块边界、数据流、接口契约，而不是某个函数怎么写</td><td>封装一个工具函数不算</td></tr><tr><td><strong>影响面大</strong></td><td>跨模块、跨团队、跨项目阶段</td><td>只影响一个文件的改动不算</td></tr><tr><td><strong>难回退</strong></td><td>错了要动骨架，改动成本高</td><td>改一行配置就能回退的不算</td></tr></tbody></table><p>所以&quot;架构师&quot;和&quot;高级开发&quot;的区别不在资历，而在<strong>决策粒度</strong>：高级开发解决复杂问题，架构师解决<strong>会扩散、会演化</strong>的问题。</p><hr><h2 id="二、架构师做什么-通用" tabindex="-1">二、架构师做什么（通用） <a class="header-anchor" href="#二、架构师做什么-通用" aria-label="Permalink to &quot;二、架构师做什么（通用）&quot;">​</a></h2><p>所有领域的架构师，日常都在做这五类事：</p><h3 id="_1-定边界" tabindex="-1">1. 定边界 <a class="header-anchor" href="#_1-定边界" aria-label="Permalink to &quot;1. 定边界&quot;">​</a></h3><p>回答&quot;这个能力归谁管&quot;。典型问题：</p><ul><li>这个逻辑放前端还是后端？（BFF 的诞生）</li><li>支付状态机谁推进、谁只读？</li><li>这个公共组件归业务组还是基建组维护？</li></ul><p>边界定的好，团队可以并行开发；边界乱了，一个需求要跨三个模块改。</p><h3 id="_2-定契约" tabindex="-1">2. 定契约 <a class="header-anchor" href="#_2-定契约" aria-label="Permalink to &quot;2. 定契约&quot;">​</a></h3><p>边界确定后，用<strong>接口</strong>把它固化下来：API 字段、事件结构、存储模型、组件 props。契约的意义在于：<strong>双方只要遵守契约，内部怎么改都不影响对方</strong>。所以契约的演进（加字段、弃用、版本化）是架构师的核心工作。</p><h3 id="_3-做权衡" tabindex="-1">3. 做权衡 <a class="header-anchor" href="#_3-做权衡" aria-label="Permalink to &quot;3. 做权衡&quot;">​</a></h3><p>架构没有最优解，只有<strong>在当前约束下损失最小</strong>的解。每次选型背后都是一串取舍：</p><ul><li>用微前端还是巨石应用？——独立部署 vs 复杂度</li><li>用强一致还是最终一致？——正确性 vs 可用性</li><li>用 SSR 还是 CSR？——首屏体验 vs 成本</li></ul><p>选型本身不值钱，<strong>把取舍讲清楚</strong>才值钱——因为取舍决定了下一次变化的代价。</p><h3 id="_4-留演进余地" tabindex="-1">4. 留演进余地 <a class="header-anchor" href="#_4-留演进余地" aria-label="Permalink to &quot;4. 留演进余地&quot;">​</a></h3><p>架构师要回答&quot;以后怎么改&quot;：扩展点画在哪、哪些决策故意做成可逆的、哪些地方现在不做将来会痛。不是预测未来，而是<strong>让不确定的部分变化代价最小</strong>。</p><h3 id="_5-让决策可逆" tabindex="-1">5. 让决策可逆 <a class="header-anchor" href="#_5-让决策可逆" aria-label="Permalink to &quot;5. 让决策可逆&quot;">​</a></h3><p>好的架构决策大多可逆：加一个适配层、抽一个接口，错了能换。不可逆的决策（选了某种存储、绑死某个平台）要尽可能推迟到信息最充分的时刻。<strong>&quot;晚一点做不可逆的决定&quot;本身就是架构手段。</strong></p><hr><h2 id="三、前端架构师-考虑的问题" tabindex="-1">三、前端架构师：考虑的问题 <a class="header-anchor" href="#三、前端架构师-考虑的问题" aria-label="Permalink to &quot;三、前端架构师：考虑的问题&quot;">​</a></h2><p>前端架构师在<strong>浏览器/客户端这个受限环境</strong>里做决策。和&quot;页面好不好看&quot;无关，他关心的是以下问题：</p><h3 id="_1-性能与体验" tabindex="-1">1. 性能与体验 <a class="header-anchor" href="#_1-性能与体验" aria-label="Permalink to &quot;1. 性能与体验&quot;">​</a></h3><p>前端架构最大的约束是<strong>用户的设备与网络不可控</strong>：</p><ul><li>首屏时间：JS 包怎么拆（路由级分包、按需加载）、资源怎么缓存（HTTP 缓存策略、ServiceWorker）</li><li>渲染性能：列表虚拟化、避免重渲染、长任务切分（requestIdleCallback / 时间切片）</li><li>体验指标：FCP / LCP / INP 哪些能改、哪些是上线前就要定的基线</li></ul><p>前端架构师要把&quot;性能&quot;变成<strong>工程机制</strong>而不是&quot;优化技巧&quot;：预算（bundle size 超了 CI 报警）、自动化的性能监控、变更即回归的压测。</p><h3 id="_2-工程化与协作" tabindex="-1">2. 工程化与协作 <a class="header-anchor" href="#_2-工程化与协作" aria-label="Permalink to &quot;2. 工程化与协作&quot;">​</a></h3><p>多人协作下代码怎么组织、怎么保证质量：</p><ul><li>构建链路：Vite / Webpack 的配置边界、构建产物优化</li><li>代码组织：Monorepo 还是多仓、包怎么拆分、依赖怎么治理</li><li>规范体系：lint / 格式化 / 提交规范 / 代码评审标准</li><li>发布策略：灰度、回滚、AB 实验怎么接</li></ul><h3 id="_3-组件体系与设计系统" tabindex="-1">3. 组件体系与设计系统 <a class="header-anchor" href="#_3-组件体系与设计系统" aria-label="Permalink to &quot;3. 组件体系与设计系统&quot;">​</a></h3><p>前端特有的复用来源是 UI 组件：</p><ul><li>组件分层：基础组件 / 业务组件 / 页面组件的边界</li><li>设计系统：样式变量、主题切换、视觉规范怎么落地为代码</li><li>组件契约：props 怎么设计才不越权（组件不该知道业务状态）</li></ul><h3 id="_4-状态与数据流" tabindex="-1">4. 状态与数据流 <a class="header-anchor" href="#_4-状态与数据流" aria-label="Permalink to &quot;4. 状态与数据流&quot;">​</a></h3><p>前端一半的复杂度在状态管理：</p><ul><li>本地状态 / 全局状态 / 服务端状态（缓存）各放哪</li><li>数据流方向（单向数据流、事件总线）和跨组件通信的规矩</li><li>服务端状态缓存：请求去重、失效策略、乐观更新</li></ul><h3 id="_5-跨端与渲染策略" tabindex="-1">5. 跨端与渲染策略 <a class="header-anchor" href="#_5-跨端与渲染策略" aria-label="Permalink to &quot;5. 跨端与渲染策略&quot;">​</a></h3><p>业务跑在哪些端、用什么渲染方式：</p><ul><li>Web / 小程序 / App（Hybrid / RN / 原生）的共用与差异</li><li>CSR / SSR / SSG / ISR 的选型与迁移路径</li><li>兼容策略：浏览器矩阵、降级方案</li></ul><h3 id="前端特有的权衡" tabindex="-1">前端特有的权衡 <a class="header-anchor" href="#前端特有的权衡" aria-label="Permalink to &quot;前端特有的权衡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权衡</th><th>两端</th><th>典型场景</th></tr></thead><tbody><tr><td>体验 vs 成本</td><td>原生体验 vs 一套代码跨端</td><td>核心流程用原生、长尾用 H5</td></tr><tr><td>运行时 vs 构建时</td><td>首屏更快 vs 构建更慢</td><td>SSR 的权衡</td></tr><tr><td>客户端 vs 服务端</td><td>逻辑放哪更安全/更省</td><td>校验、权限、埋点</td></tr><tr><td>框架 vs 自研</td><td>跟生态 vs 完全可控</td><td>组件库选型</td></tr></tbody></table><p><strong>一句话总结前端架构</strong>：在设备、网络、浏览器兼容三重不可控下，把&quot;体验&quot;做成可持续的工程体系。</p><hr><h2 id="四、后端架构师-考虑的问题" tabindex="-1">四、后端架构师：考虑的问题 <a class="header-anchor" href="#四、后端架构师-考虑的问题" aria-label="Permalink to &quot;四、后端架构师：考虑的问题&quot;">​</a></h2><p>后端架构师面对的世界是<strong>多用户并发、数据要持久、系统要 7×24 可用</strong>。他关心的是：</p><h3 id="_1-数据与存储" tabindex="-1">1. 数据与存储 <a class="header-anchor" href="#_1-数据与存储" aria-label="Permalink to &quot;1. 数据与存储&quot;">​</a></h3><ul><li>数据模型设计：实体关系、字段设计、索引策略</li><li>存储选型：MySQL / PostgreSQL / MongoDB / Redis 各管什么</li><li>规模演进：分库分表、读写分离、归档策略</li></ul><h3 id="_2-服务划分" tabindex="-1">2. 服务划分 <a class="header-anchor" href="#_2-服务划分" aria-label="Permalink to &quot;2. 服务划分&quot;">​</a></h3><ul><li>模块边界：按业务域切（订单、库存、用户）还是按技术层切</li><li>微服务 vs 单体：独立部署 vs 分布式复杂度（网络、事务、排查）</li><li>服务间通信：同步（RPC / HTTP）vs 异步（消息队列），谁调用谁、谁依赖谁</li></ul><h3 id="_3-接口契约" tabindex="-1">3. 接口契约 <a class="header-anchor" href="#_3-接口契约" aria-label="Permalink to &quot;3. 接口契约&quot;">​</a></h3><ul><li>API 设计：资源模型、语义、错误码规范</li><li>版本演进：兼容旧客户端、废弃策略</li><li>幂等性：重试安全、重复提交防护</li></ul><h3 id="_4-一致性与可靠性" tabindex="-1">4. 一致性与可靠性 <a class="header-anchor" href="#_4-一致性与可靠性" aria-label="Permalink to &quot;4. 一致性与可靠性&quot;">​</a></h3><ul><li>事务边界：ACID 在哪层保证</li><li>分布式一致性：最终一致、分布式事务（TCC / SAGA / 本地消息表）</li><li>故障应对：重试、超时、熔断、降级、限流——<strong>先保可用再保正确</strong>的取舍</li></ul><h3 id="_5-容量与性能" tabindex="-1">5. 容量与性能 <a class="header-anchor" href="#_5-容量与性能" aria-label="Permalink to &quot;5. 容量与性能&quot;">​</a></h3><ul><li>并发模型：连接池、线程模型、异步化</li><li>缓存策略：缓存什么、失效策略、缓存一致性</li><li>削峰：消息队列缓冲、批处理</li></ul><h3 id="_6-安全" tabindex="-1">6. 安全 <a class="header-anchor" href="#_6-安全" aria-label="Permalink to &quot;6. 安全&quot;">​</a></h3><ul><li>认证授权：会话 / JWT、RBAC 权限模型、数据权限隔离</li><li>数据安全：SQL 注入、敏感数据加密、脱敏</li><li>接口安全：防刷、限流、CSRF</li></ul><h3 id="_7-可观测性与运维" tabindex="-1">7. 可观测性与运维 <a class="header-anchor" href="#_7-可观测性与运维" aria-label="Permalink to &quot;7. 可观测性与运维&quot;">​</a></h3><ul><li>日志规范：结构化日志、请求追踪 ID</li><li>指标与告警：核心链路指标、容量水位</li><li>链路追踪：跨服务问题怎么定位</li><li>发布运维：CI/CD、灰度、蓝绿、回滚预案</li></ul><h3 id="后端特有的权衡" tabindex="-1">后端特有的权衡 <a class="header-anchor" href="#后端特有的权衡" aria-label="Permalink to &quot;后端特有的权衡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权衡</th><th>两端</th><th>典型场景</th></tr></thead><tbody><tr><td>一致性 vs 可用性</td><td>强一致 vs 最终一致</td><td>CAP 的取舍</td></tr><tr><td>正确性 vs 性能</td><td>严格校验 vs 快速响应</td><td>缓存、异步化</td></tr><tr><td>单体 vs 微服务</td><td>简单 vs 独立扩展</td><td>团队规模、流量规模</td></tr><tr><td>同步 vs 异步</td><td>简单直接 vs 削峰解耦</td><td>下单流程、通知</td></tr></tbody></table><p><strong>一句话总结后端架构</strong>：在多用户、数据、故障的三重压力下，把&quot;正确性&quot;和&quot;可用性&quot;做成可持续的系统能力。</p><hr><h2 id="五、前端-vs-后端-核心矛盾的差异" tabindex="-1">五、前端 vs 后端：核心矛盾的差异 <a class="header-anchor" href="#五、前端-vs-后端-核心矛盾的差异" aria-label="Permalink to &quot;五、前端 vs 后端：核心矛盾的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>前端架构师</th><th>后端架构师</th></tr></thead><tbody><tr><td>首要约束</td><td>设备、网络、浏览器兼容</td><td>并发、数据一致性、可用性</td></tr><tr><td>核心矛盾</td><td><strong>体验与复杂度的平衡</strong></td><td><strong>正确性与规模的平衡</strong></td></tr><tr><td>主要风险</td><td>首屏慢、卡顿、兼容崩</td><td>数据错、服务挂、扩容难</td></tr><tr><td>架构载体</td><td>组件体系、状态流、构建链路</td><td>服务边界、存储模型、消息链路</td></tr><tr><td>失败的代价</td><td>用户流失、口碑受损</td><td>资损、系统瘫痪</td></tr><tr><td>演进动力</td><td>业务形态变化（跨端、新渲染方式）</td><td>规模变化（流量、数据量、团队）</td></tr><tr><td>最难的决策</td><td>边界画错→改造成本高且牵动体验</td><td>数据模型/服务边界定错→几乎重来</td></tr></tbody></table><p>一个直观比喻：<strong>前端架构像城市规划——道路（构建链路）、街区（模块）、地标（组件）怎么布局，决定城市好不好用；后端架构像水利工程——水源（数据）、管道（服务）、闸门（限流降级）怎么设计，决定系统会不会决堤。</strong> 前者服务&quot;人的体验&quot;，后者服务&quot;系统的存续&quot;。</p><hr><h2 id="六、架构师的思维模式" tabindex="-1">六、架构师的思维模式 <a class="header-anchor" href="#六、架构师的思维模式" aria-label="Permalink to &quot;六、架构师的思维模式&quot;">​</a></h2><p>把&quot;架构师怎么做决策&quot;提炼成几条可练习的思维：</p><ol><li><strong>权衡，不是最优</strong>：面试/讨论时说&quot;我选了 X，因为当时约束是 Y，代价是 Z，将来如果 A 变了会换成 B&quot;——这就是架构师语言</li><li><strong>边界比实现重要</strong>：先画清楚&quot;谁负责什么、谁依赖谁&quot;，再谈具体技术</li><li><strong>契约先于实现</strong>：接口定了，两端可以并行开工，这是架构决策的杠杆</li><li><strong>决策要可逆</strong>：能做成可逆的就不做不可逆的；不可逆的推迟做</li><li><strong>简单优先，演进驱动</strong>：不为假想的未来加抽象；等真实需求出现，用最小代价演进（参考 YAGNI 与渐进式架构）</li><li><strong>反面教材：过度设计</strong>——为一年后可能出现的需求设计三层抽象，是架构新手最常见的错误。架构是&quot;应对变化的最小结构&quot;，不是&quot;预测变化的全部结构&quot;</li></ol><hr><h2 id="七、从开发到架构师-怎么练" tabindex="-1">七、从开发到架构师：怎么练 <a class="header-anchor" href="#七、从开发到架构师-怎么练" aria-label="Permalink to &quot;七、从开发到架构师：怎么练&quot;">​</a></h2><p>架构能力不是&quot;学了架构课&quot;就会，而是<strong>在具体项目里反复做结构性决策</strong>练出来的。练习路径：</p><ol><li><strong>先把一个模块当系统设计</strong>：你负责的页面/服务，画出它的边界、数据流、扩展点——哪怕很小，练习&quot;结构性视角&quot;</li><li><strong>给每个方案记权衡</strong>：做技术选型时，写下&quot;选了 A 放弃了 B，因为……代价是……&quot;——这是架构决策的存档习惯</li><li><strong>主动画边界</strong>：开发时发现&quot;这个逻辑放这里怪怪的&quot;，停下来想想应该放哪——这就是架构直觉的来源</li><li><strong>读别人的架构</strong>：看知名开源项目的目录结构、模块依赖方向，问&quot;为什么这么切&quot;（你研究过的 dsh 插件化设计就是一个很好的样本）</li><li><strong>在评审里练表达</strong>：代码评审时讨论的不是&quot;这段代码对不对&quot;，而是&quot;这个边界划得对不对&quot;</li></ol><p>前端转全栈的路径上，<strong>前端架构师和后端架构师的知识是互补的</strong>：前端的体验约束会让后端方案更务实（BFF 就是前端视角催生的架构），后端的正确性思维会让前端方案更严谨（接口契约、错误处理）。全栈架构师不是&quot;两个都会&quot;，而是<strong>两边的权衡都看得见，能在边界上做全局最优的决策</strong>——这恰恰是架构师区别于单领域工程师的核心能力。</p><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/engineering/bff.html">BFF 层设计</a> - 前后端边界上的典型架构决策</li><li><a href="/knowledge/engineering/monorepo.html">Monorepo 介绍与实践</a> - 工程组织层面的架构决策</li><li><a href="/knowledge/engineering/team-management.html">团队管理最佳实践</a> - 架构决策如何在团队落地</li><li><a href="/knowledge/ai-agent/harness-engineering/quality-control.html">质量控制对比</a> - 把质量做成机制的工程思维</li></ul>',84)])])}const c=a(i,[["render",e]]);export{g as __pageData,c as default};
